<script>
(function() {
    var SCORE_COLORS = [
        '#d73737','#d83c37','#d94237','#da4736','#db4d36','#dc5336','#dd5936','#df5f36','#e06535','#e16b35',
        '#e27135','#e37735','#e47e35','#e58434','#e68b34','#e79134','#e89834','#e99f33','#eaa633','#ecad33',
        '#edb433','#eebb33','#efc232','#f0ca32','#f1d132','#f1d132','#ebd531','#e6d930','#e1dc2f','#d7db2e',
        '#cad52d','#bdd02c','#b0cb2c','#a4c52b','#98bf2a','#8dba29','#82b428','#78af27','#6eaa26','#65a425',
        '#5c9e24','#539923','#4b9322','#438e21','#3c8821','#358320','#2f7d1f','#29781e','#23721d','#1e6d1c'
    ];

    function getScoreColor(score) {
        var idx;
        if (score <= 40) {
            idx = Math.floor(score / 1.6);
            idx = Math.max(0, Math.min(24, idx));
        } else {
            idx = 25 + Math.floor((score - 40) / 3.4);
            idx = Math.max(25, Math.min(49, idx));
        }
        return SCORE_COLORS[idx];
    }

// Green gradient for positive luck, red gradient for negative luck.
// Intensity scales with magnitude (capped at 45).
function getLuckColor(lv) {
    var mag = Math.min(Math.abs(lv), 45);
    var t = mag / 45; // 0..1
    if (lv >= 0) {
        // light green -> deep green
        var r = Math.round(134 + (30 - 134) * t);
        var g = Math.round(190 + (120 - 190) * t);
        var b = Math.round(140 + (35 - 140) * t);
        return 'rgb(' + r + ',' + g + ',' + b + ')';
    } else {
        // light red -> deep red
        var r2 = Math.round(224 + (175 - 224) * t);
        var g2 = Math.round(110 + (35 - 110) * t);
        var b2 = Math.round(110 + (35 - 110) * t);
        return 'rgb(' + r2 + ',' + g2 + ',' + b2 + ')';
    }
}

    var availablePCs = Object.keys(byPC).map(Number).sort(function(a, b) { return a - b; });
    var ALL_PCS = [50, 100, 250, 500, 1000];
    var currentPC = availablePCs.indexOf(100) !== -1 ? 100 : (availablePCs[0] || 100);
    var viewMode = 'both';

    var pcRow = document.getElementById('lu-pc-row');
    var leftCol = document.getElementById('lu-left');
    var rightCol = document.getElementById('lu-right');
    var btnLucky = document.getElementById('lu-btn-lucky');
    var btnUnlucky = document.getElementById('lu-btn-unlucky');

    function buildPCButtons() {
        pcRow.innerHTML = ALL_PCS.map(function(pc) {
            var available = availablePCs.indexOf(pc) !== -1;
            var active = pc === currentPC;
            var cls = 'lu-pc-btn';
            if (pc === 50) cls += ' lu-pc-first';
            if (!available) cls += ' disabled';
            else if (active) cls += ' active';
            var label = pc === 50 ? 'Last 50 Pitches' : '<span class="lu-pc-last-full">Last </span><span class="lu-pc-last-short">L </span>' + pc.toLocaleString();
            return '<button class="' + cls + '" data-pc="' + pc + '">' + label + '</button>';
        }).join('');

        var btns = pcRow.querySelectorAll('.lu-pc-btn:not(.disabled)');
        for (var i = 0; i < btns.length; i++) {
            (function(btn) {
                btn.addEventListener('click', function() {
                    currentPC = parseInt(btn.getAttribute('data-pc'));
                    buildPCButtons();
                    render();
                });
            })(btns[i]);
        }
    }

    var tooltip = document.getElementById('lu-tooltip');
    var tooltipTimer = null;
    var isTouch = 'ontouchstart' in window;

    function showTooltip(anchor) {
        if (tooltipTimer) { clearTimeout(tooltipTimer); tooltipTimer = null; }
        tooltip.textContent = 'Views for higher pitch counts need more 2026 data to be collected';
        tooltip.classList.add('visible');
        var btnRect = anchor.getBoundingClientRect();
        var wrapRect = anchor.closest('[style*="position"]').getBoundingClientRect();
        tooltip.style.position = 'absolute';
        var tipW = tooltip.offsetWidth;
        var left = (btnRect.left - wrapRect.left) + btnRect.width / 2 - tipW / 2;
        if (left < 4) left = 4;
        if (left + tipW > wrapRect.width - 4) left = wrapRect.width - 4 - tipW;
        tooltip.style.left = left + 'px';
        tooltip.style.top = (btnRect.bottom - wrapRect.top + 6) + 'px';
        tooltipTimer = setTimeout(function() { tooltip.classList.remove('visible'); }, 3000);
    }

    function hideTooltip() {
        if (tooltipTimer) { clearTimeout(tooltipTimer); tooltipTimer = null; }
        tooltip.classList.remove('visible');
    }

    pcRow.addEventListener('click', function(e) {
        var btn = e.target.closest('.lu-pc-btn.disabled');
        if (btn && isTouch) { showTooltip(btn); }
    });
    pcRow.addEventListener('mouseover', function(e) {
        if (isTouch) return;
        var btn = e.target.closest('.lu-pc-btn.disabled');
        if (btn) { showTooltip(btn); }
    });
    pcRow.addEventListener('mouseout', function(e) {
        if (isTouch) return;
        var btn = e.target.closest('.lu-pc-btn.disabled');
        if (btn) { hideTooltip(); }
    });
    document.addEventListener('click', function(e) {
        if (!e.target.closest('.lu-pc-btn.disabled') && !e.target.closest('.lu-tooltip')) {
            hideTooltip();
        }
    });

    function getLucky(pc) {
        return (byPC[pc] || []).filter(function(d) { return d.lr <= 10; }).sort(function(a, b) { return a.lr - b.lr; });
    }

    function getUnlucky(pc) {
        return (byPC[pc] || []).filter(function(d) { return d.ur <= 10; }).sort(function(a, b) { return a.ur - b.ur; });
    }

    function escHtml(s) {
        var el = document.createElement('span');
        el.textContent = s;
        return el.innerHTML;
    }

    function shortName(name) {
        if (name.length <= 15) return name;
        var parts = name.split(' ');
        if (parts.length < 2) return name;
        return parts[0].charAt(0) + '. ' + parts.slice(1).join(' ');
    }

    function initialName(name) {
        var parts = name.split(' ');
        if (parts.length < 2) return name;
        return parts[0].charAt(0) + '. ' + parts.slice(1).join(' ');
    }

    function parseStatLine(s) {
        if (!s) return [];
        var parts = s.split(',');
        var stats = [];
        for (var i = 0; i < parts.length; i++) {
            var part = parts[i].trim();
            // Accept signed values like "+1.5" or "-0.3"
            var m = part.match(/^([+\-]?[\d.]+)\s+(?:exp\s+)?(.+)$/);
            if (m) {
                var val = m[1];
                var label = m[2];
                if (label === 'HRs') label = 'HR';
                else if (label === 'Hits') label = 'H';
                else if (label === 'Bases') label = 'TB';
                else if (label === 'BBs') label = 'BB';
                else if (label === 'Ks') label = 'K';
                stats.push({ val: val, label: label });
            }
        }
        return stats;
    }

    function buildCard(d, type, rank) {
        var page = d.bt ? 'Batter-Summary' : 'Pitcher-Summary';
        var href = page + '.php?PlayerId=' + d.pid;
        var bgClass = type === 'lucky' ? 'lucky-bg' : 'unlucky-bg';
        var headshot = 'https://img.mlbstatic.com/mlb-photos/image/upload/w_80,q_100/v1/people/' + d.pid + '/headshot/silo/current';
        var evColor = getScoreColor(d.ev);
        var avColor = getScoreColor(d.av);
        var lvColor = getLuckColor(d.lv);
        var lvText = (d.lv > 0 ? '+' : '') + d.lv;
        var stats = parseStatLine(d.stat);
        var statsHtml = '<div class="lu-stats">';
        for (var i = 0; i < stats.length; i++) {
            statsHtml += '<span class="lu-stat"><b>' + stats[i].val + '</b> ' + stats[i].label + '</span>';
        }
        statsHtml += '</div>';
        return '<a href="' + href + '" class="lu-card ' + bgClass + '">' +
            '<span class="lu-rank">' + rank + '</span>' +
            '<img src="' + headshot + '" class="lu-headshot" alt="" />' +
            '<div class="lu-info">' +
                '<div class="lu-score-cluster">' +
                    '<div class="lu-score-top">' +
                        '<span class="lu-score-small" style="background:' + evColor + '">' + d.ev + '</span>' +
                        '<span class="lu-score-small" style="background:' + avColor + '">' + d.av + '</span>' +
                    '</div>' +
                    '<span class="lu-score-main" style="background:' + lvColor + '">' + lvText + '</span>' +
                '</div>' +
                '<div class="lu-detail">' +
                    '<div class="lu-name">' +
                        '<span class="lu-name-desktop">' + escHtml(shortName(d.name)) + '</span>' +
                        '<span class="lu-name-mobile">' + escHtml(initialName(d.name)) + '</span>' +
                    '</div>' +
                    statsHtml +
                '</div>' +
            '</div>' +
        '</a>';
    }

    function render() {
        var leftItems, rightItems, leftType, rightType;

        if (viewMode === 'both') {
            leftItems = getLucky(currentPC).slice(0, 5);
            rightItems = getUnlucky(currentPC).slice(0, 5);
            leftType = 'lucky';
            rightType = 'unlucky';
        } else if (viewMode === 'lucky') {
            var lucky = getLucky(currentPC);
            leftItems = lucky.slice(0, 5);
            rightItems = lucky.slice(5, 10);
            leftType = 'lucky';
            rightType = 'lucky';
        } else {
            var unlucky = getUnlucky(currentPC);
            leftItems = unlucky.slice(0, 5);
            rightItems = unlucky.slice(5, 10);
            leftType = 'unlucky';
            rightType = 'unlucky';
        }

        var leftStart = 1;
        var rightStart = viewMode === 'both' ? 1 : 6;
        leftCol.innerHTML = leftItems.map(function(d, i) { return buildCard(d, leftType, leftStart + i); }).join('');
        rightCol.innerHTML = rightItems.map(function(d, i) { return buildCard(d, rightType, rightStart + i); }).join('');

        btnLucky.classList.toggle('inactive', viewMode === 'unlucky');
        btnUnlucky.classList.toggle('inactive', viewMode === 'lucky');
    }

    btnLucky.addEventListener('click', function() {
        if (viewMode === 'both') viewMode = 'lucky';
        else viewMode = 'both';
        render();
    });

    btnUnlucky.addEventListener('click', function() {
        if (viewMode === 'both') viewMode = 'unlucky';
        else viewMode = 'both';
        render();
    });

    buildPCButtons();
    render();

    document.getElementById('lu-guide-link').addEventListener('click', function() {
        document.getElementById('rfKeyOverlay').classList.add('is-open');
    });
})();
</script>

    var STREAK_TYPES = [
        { key: 'Hit', thr: 1, label: '1+ Hits' },
        { key: 'On Base', thr: 1, label: 'On Base' },
        { key: 'Total Bases', thr: 2, label: '2+ Bases' },
        { key: 'Home Run', thr: 1, label: '1+ HR' },
        { key: 'Walk', thr: 1, label: '1+ BB' },
        { key: 'Stolen Bases', thr: 1, label: '1+ SB' },
        { key: 'Strikeout', thr: 1, label: '1+ K' }
    ];

    var currentType = STREAK_TYPES[0];
    var currentBreaks = 1;

    var typeRow = document.getElementById('hs-type-row');
    var leftCol = document.getElementById('hs-left');
    var rightCol = document.getElementById('hs-right');

    function buildTypeButtons() {
        typeRow.innerHTML = STREAK_TYPES.map(function(t) {
            var cls = 'hs-type-btn';
            if (t.key === currentType.key) cls += ' active';
            return '<button class="' + cls + '" data-type="' + t.key + '">' + t.label + '</button>';
        }).join('');

        var btns = typeRow.querySelectorAll('.hs-type-btn');
        for (var i = 0; i < btns.length; i++) {
            (function(btn) {
                btn.addEventListener('click', function() {
                    var key = btn.getAttribute('data-type');
                    for (var j = 0; j < STREAK_TYPES.length; j++) {
                        if (STREAK_TYPES[j].key === key) { currentType = STREAK_TYPES[j]; break; }
                    }
                    buildTypeButtons();
                    render();
                });
            })(btns[i]);
        }
    }

    var breakBtns = document.querySelectorAll('.hs-break-btn');
    for (var i = 0; i < breakBtns.length; i++) {
        (function(btn) {
            btn.addEventListener('click', function() {
                currentBreaks = parseInt(btn.getAttribute('data-breaks'));
                for (var j = 0; j < breakBtns.length; j++) {
                    breakBtns[j].classList.toggle('active', parseInt(breakBtns[j].getAttribute('data-breaks')) === currentBreaks);
                }
                render();
            });
        })(breakBtns[i]);
    }

    function getStreaks() {
        return allData.filter(function(d) {
            return d.st === currentType.key && d.thr === currentType.thr && d.sb === currentBreaks;
        }).sort(function(a, b) { return a.rank - b.rank; });
    }

    function escHtml(s) {
        var el = document.createElement('span');
        el.textContent = s;
        return el.innerHTML;
    }

    function shortName(name) {
        if (name.length <= 14) return name;
        var parts = name.split(' ');
        if (parts.length < 2) return name;
        return parts[0].charAt(0) + '. ' + parts.slice(1).join(' ');
    }

    function buildStreakBar(d) {
        var breaks = [];
        if (d.b1 !== null) breaks.push(d.b1);
        if (d.b2 !== null) breaks.push(d.b2);
        if (d.b3 !== null) breaks.push(d.b3);
        var total = d.gc + d.sb;
        var html = '<div class="hs-streak-bar">';
        for (var i = 1; i <= total; i++) {
            var cls = breaks.indexOf(i) !== -1 ? 'fail' : 'success';
            html += '<span class="hs-box ' + cls + '"></span>';
        }
        html += '</div>';
        return html;
    }

    function buildCard(d) {
        var href = 'Batter-Summary.php?PlayerId=' + d.pid;
        var headshot = 'https://img.mlbstatic.com/mlb-photos/image/upload/w_80,q_100/v1/people/' + d.pid + '/headshot/silo/current';
        return '<a href="' + href + '" class="hs-card">' +
            '<img src="' + headshot + '" class="hs-headshot" alt="" />' +
            '<div class="hs-info">' +
                '<span class="hs-score">' + d.gc + '</span>' +
                '<div class="hs-detail">' +
                    '<div class="hs-name">' + escHtml(shortName(d.name)) + '</div>' +
                    buildStreakBar(d) +
                '</div>' +
            '</div>' +
        '</a>';
    }

    function render() {
        var items = getStreaks();
        var left = items.slice(0, 5);
        var right = items.slice(5, 10);
        leftCol.innerHTML = left.map(function(d) { return buildCard(d); }).join('');
        rightCol.innerHTML = right.map(function(d) { return buildCard(d); }).join('');
    }

    buildTypeButtons();
    render();
})();
</script>

